"""Canonical topology model: directed flows, counter keys and router views.

Physical links create both directed flows and share one capacity.  External
nodes create the sentinel flows ``(-1, node)`` and ``(node, -1)`` bounded by
that node's external capacity.  The sentinel is never a router.
"""

from .domain import DomainError


class Topology:
    """Immutable view of one stream topology."""

    def __init__(self, raw):
        if not isinstance(raw, dict):
            raise DomainError('topology must be an object')
        for field in ('nodes', 'links', 'external_nodes'):
            if field not in raw:
                raise DomainError('topology field %s missing' % field)
        nodes = raw['nodes']
        links = raw['links']
        external = raw['external_nodes']
        if not isinstance(nodes, list) or not isinstance(links, list) \
                or not isinstance(external, list):
            raise DomainError('topology containers must be arrays/objects')

        self.name_by_id = {}
        self.id_by_name = {}
        self.node_ids = []
        declared_caps = {}
        for node in nodes:
            if not isinstance(node, dict):
                raise DomainError('node must be an object')
            try:
                nid = node['id']
                name = node['name']
                capacity = node['external_capacity']
            except KeyError as exc:
                raise DomainError('node field %s missing' % exc)
            if type(nid) is not int or type(capacity) is not int:
                raise DomainError('node id/capacity must be integers')
            if not isinstance(name, str):
                raise DomainError('node name must be a string')
            if nid in self.name_by_id or name in self.id_by_name:
                raise DomainError('node ids and names must be distinct')
            self.name_by_id[nid] = name
            self.id_by_name[name] = nid
            declared_caps[nid] = capacity
            self.node_ids.append(nid)

        self.link_cap = {}
        for link in links:
            if not isinstance(link, dict):
                raise DomainError('link must be an object')
            try:
                source = link['source']
                target = link['target']
                capacity = link['capacity']
            except KeyError as exc:
                raise DomainError('link field %s missing' % exc)
            if type(source) is not int or type(target) is not int \
                    or type(capacity) is not int:
                raise DomainError('link fields must be integers')
            if source not in self.name_by_id or target not in self.name_by_id:
                raise DomainError('link endpoint is not an existing node')
            if source == target:
                raise DomainError('link endpoints must differ')
            undirected = (source, target) if source < target else (target, source)
            if undirected in self.link_cap:
                raise DomainError('parallel physical link')
            self.link_cap[undirected] = capacity

        self.external_ids = []
        self.external_caps = {}
        seen = set()
        for name in external:
            if not isinstance(name, str) or name not in self.id_by_name:
                raise DomainError('external node name is not a known node')
            nid = self.id_by_name[name]
            if nid in seen:
                raise DomainError('external nodes must be distinct')
            seen.add(nid)
            self.external_ids.append(nid)
            self.external_caps[nid] = declared_caps[nid]
        self.external_ids.sort()
        self.external_id_set = frozenset(self.external_ids)

        # Directed flows in canonical (ascending pair) order, sentinel first.
        flows = []
        for (left, right), capacity in self.link_cap.items():
            flows.append((left, right, capacity))
            flows.append((right, left, capacity))
        for nid in self.external_ids:
            capacity = self.external_caps[nid]
            flows.append((-1, nid, capacity))
            flows.append((nid, -1, capacity))
        flows.sort(key=lambda item: (item[0], item[1]))
        self.flows = flows
        self.flow_count = len(flows)

        self.flow_index = {}
        self.flow_cap = []
        self.flow_keys = []
        self.flow_key_list = []
        self.flow_endpoints = []
        self.key_to_flow = {}
        for index, (source, target, capacity) in enumerate(flows):
            self.flow_index[(source, target)] = index
            self.flow_cap.append(capacity)
            if source == -1:
                src_key = None
                dst_key = 'low_%s_origination' % self.name_by_id[target]
            elif target == -1:
                src_key = 'low_%s_termination' % self.name_by_id[source]
                dst_key = None
            else:
                src_key = 'low_%s_egress_to_%s' % (
                    self.name_by_id[source], self.name_by_id[target])
                dst_key = 'low_%s_ingress_from_%s' % (
                    self.name_by_id[target], self.name_by_id[source])
            keys = []
            if src_key is not None:
                keys.append(src_key)
            if dst_key is not None:
                keys.append(dst_key)
            self.flow_keys.append((src_key, dst_key))
            self.flow_key_list.append(tuple(keys))
            for key in keys:
                self.key_to_flow[key] = index
            if source == -1:
                self.flow_endpoints.append((target,))
            elif target == -1:
                self.flow_endpoints.append((source,))
            else:
                self.flow_endpoints.append((source, target))
        self.counter_keys = frozenset(self.key_to_flow)

        # Router-centric incidence: (flow index, is outgoing from router).
        self.router_flows = {nid: [] for nid in self.node_ids}
        for index, (source, target, _capacity) in enumerate(flows):
            if source != -1:
                self.router_flows[source].append((index, True))
            if target != -1:
                self.router_flows[target].append((index, False))

        # Semantic identity of the topology for repair memoisation.
        self.norm = (
            tuple(sorted((nid, self.name_by_id[nid]) for nid in self.node_ids)),
            tuple(sorted(self.link_cap.items())),
            tuple(sorted((self.name_by_id[nid], self.external_caps[nid])
                         for nid in self.external_ids)),
        )

    def is_external(self, nid):
        return nid in self.external_id_set
